      "file": "t04.js",
      "line": 7,
      "evidence": "app.get('/api/feature-flags', ...)",
      "llm_reasoning": "The endpoint exposes configuration data without any rate limiting, making it susceptible to enumeration or brute-force attempts if the configuration contains sensitive keys.",
      "suggested_fix": "Implement express-rate-limit middleware to restrict the number of requests per IP."
